textOptions.schema:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "locale",
    "meta",
    "procedures",
    "items",
    "caption"
  ],
  "properties": {
    "locale": {
      "type": "string",
      "const": "pt-BR",
      "description": "Idioma obrigatório de todo texto humano neste JSON. Sempre retornar exatamente pt-BR."
    },
    "meta": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "sourceUrls",
        "notes"
      ],
      "properties": {
        "sourceUrls": {
          "type": "array",
          "description": "Lista de URLs consultadas para rastreabilidade. Quando não houver URLs consultadas, usar array vazio.",
          "items": {
            "type": "string"
          }
        },
        "notes": {
          "type": "string",
          "minLength": 1,
          "description": "Observação interna curta em pt-BR. Deve resumir mídia, análise auxiliar, catálogo CRM e/ou Documents exclusivamente editorial, sem inserir dados comerciais vindos de contexto não autorizado."
        }
      }
    },
    "procedures": {
      "type": "array",
      "description": "Lista de procedimentos identificados com segurança. Se nada for identificado com evidência suficiente, retornar array vazio.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "name",
          "evidence",
          "adsPricing",
          "crmPricing"
        ],
        "properties": {
          "name": {
            "type": "string",
            "description": "Nome do procedimento em pt-BR. Quando houver base clara na mídia, prefira nome mais útil e específico."
          },
          "evidence": {
            "type": "string",
            "description": "Evidência objetiva do procedimento, como texto visível, rótulo, chamada promocional ou elemento visual claro, em pt-BR."
          },
          "adsPricing": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "value",
              "offer"
            ],
            "properties": {
              "value": {
                "type": "string",
                "description": "Valor visível e legível na mídia, sem tratar a mídia como fonte oficial do catálogo."
              },
              "offer": {
                "type": "string",
                "description": "Oferta ou condição visível e legível na mídia, sem tratar a mídia como fonte oficial do catálogo."
              }
            }
          },
          "crmPricing": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "value",
              "offer",
              "source"
            ],
            "properties": {
              "value": {
                "type": "string",
                "description": "Preço somente quando retornado de forma inequívoca pelo catálogo comercial oficial do CRM; caso contrário, string vazia."
              },
              "offer": {
                "type": "string",
                "description": "Oferta, combo, parcelamento, condição ou vigência somente quando retornados de forma inequívoca pelo catálogo comercial oficial do CRM; caso contrário, string vazia."
              },
              "source": {
                "type": "string",
                "enum": [
                  "crm",
                  "none"
                ],
                "description": "crm somente para retorno comercial inequívoco e válido para as duas unidades; none sem retorno comum válido."
              }
            }
          }
        }
      }
    },
    "items": {
      "type": "array",
      "description": "Itens por mídia, respeitando exatamente o índice original de media[]. Não duplicar índice sem necessidade real.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "index",
          "title",
          "alt_text",
          "mediaType",
          "bestFrame",
          "frameCandidates"
        ],
        "properties": {
          "index": {
            "type": "number",
            "multipleOf": 1,
            "description": "Índice 0-based do item em media[]. Use número inteiro."
          },
          "title": {
            "type": "string",
            "minLength": 1,
            "maxLength": 80,
            "description": "Título curto, em uma linha, em pt-BR. Deve resumir a peça com clareza e utilidade. Não repetir a legenda."
          },
          "alt_text": {
            "type": "string",
            "minLength": 1,
            "maxLength": 240,
            "description": "Texto alternativo acessível em pt-BR, objetivo, claro, descritivo e sem CTA. Não prometer resultado."
          },
          "mediaType": {
            "type": "string",
            "enum": [
              "image",
              "video",
              "unknown"
            ],
            "description": "Tipo detectado da mídia."
          },
          "bestFrame": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "applicable",
              "bestTimestamp",
              "bestTimestampSeconds",
              "reason",
              "confidence",
              "candidates",
              "selectedFrameUrl",
              "selectedFrameRank",
              "selectedFrameSource"
            ],
            "properties": {
              "applicable": {
                "type": "boolean",
                "description": "True somente quando houver escolha de frame aplicável para vídeo."
              },
              "bestTimestamp": {
                "type": "string",
                "description": "Timestamp do melhor frame em MM:SS ou HH:MM:SS. Se não aplicável, retornar string vazia."
              },
              "bestTimestampSeconds": {
                "type": "number",
                "description": "Timestamp em segundos. Se não aplicável, retornar 0."
              },
              "reason": {
                "type": "string",
                "description": "Motivo objetivo da escolha do frame em pt-BR. Se não aplicável, explicar brevemente a limitação ou retornar string vazia conforme necessário."
              },
              "confidence": {
                "type": "number",
                "minimum": 0,
                "maximum": 1,
                "description": "Confiança da escolha entre 0 e 1. Se não aplicável, usar 0."
              },
              "candidates": {
                "type": "array",
                "description": "Alternativas de frame consideradas. Se não aplicável, retornar array vazio.",
                "items": {
                  "type": "object",
                  "additionalProperties": false,
                  "required": [
                    "timestamp",
                    "timestampSeconds",
                    "reason",
                    "confidence"
                  ],
                  "properties": {
                    "timestamp": {
                      "type": "string",
                      "description": "Timestamp alternativo em MM:SS ou HH:MM:SS."
                    },
                    "timestampSeconds": {
                      "type": "number",
                      "description": "Timestamp alternativo em segundos."
                    },
                    "reason": {
                      "type": "string",
                      "description": "Motivo objetivo em pt-BR."
                    },
                    "confidence": {
                      "type": "number",
                      "minimum": 0,
                      "maximum": 1,
                      "description": "Confiança entre 0 e 1."
                    }
                  }
                }
              },
              "selectedFrameUrl": {
                "type": "string",
                "description": "URL do frame escolhido como thumbnail definitivo. Se não aplicável ou se não houver candidato utilizável, retornar string vazia."
              },
              "selectedFrameRank": {
                "type": "number",
                "description": "Rank do frame escolhido. Se não aplicável, retornar 0."
              },
              "selectedFrameSource": {
                "type": "string",
                "enum": [
                  "candidates",
                  "fallback",
                  "technical_frame_upload",
                  "none"
                ],
                "description": "Fonte da escolha. Usar candidates quando vier dos candidatos recebidos, technical_frame_upload quando vier do fallback técnico de thumbnails, fallback quando houver fallback controlado ou none quando não aplicável. Nunca retornar null."
              }
            }
          },
          "frameCandidates": {
            "type": "array",
            "description": "Frames candidatos recebidos para seleção de thumbnail. Se não houver, retornar array vazio.",
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "url",
                "rank",
                "timestamp",
                "timestampSeconds",
                "confidence",
                "reason"
              ],
              "properties": {
                "url": {
                  "type": "string",
                  "description": "URL do frame candidato."
                },
                "rank": {
                  "type": "number",
                  "description": "Ordem do candidato. 1 representa o melhor do analisador técnico."
                },
                "timestamp": {
                  "type": "string",
                  "description": "Timestamp do frame em MM:SS ou HH:MM:SS."
                },
                "timestampSeconds": {
                  "type": "number",
                  "description": "Timestamp em segundos."
                },
                "confidence": {
                  "type": "number",
                  "minimum": 0,
                  "maximum": 1,
                  "description": "Confiança do analisador técnico entre 0 e 1."
                },
                "reason": {
                  "type": "string",
                  "description": "Motivo objetivo do candidato em pt-BR."
                }
              }
            }
          }
        }
      }
    },
    "caption": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "instagram",
        "facebook",
        "threads"
      ],
      "description": "Legendas estruturadas em pt-BR. O texto final consolidado pode ser montado downstream a partir desses blocos.",
      "properties": {
        "instagram": {
          "type": "object",
          "additionalProperties": false,
