              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 420
              }
            },
            "cta": {
              "type": "string",
              "minLength": 1,
              "maxLength": 220,
              "description": "Fechamento natural e comercial para Instagram."
            },
            "hashtags": {
              "type": "array",
              "maxItems": 8,
              "description": "Hashtags moderadas para Instagram. Pode retornar array vazio quando não fizer sentido.",
              "items": {
                "type": "string",
                "minLength": 2,
                "maxLength": 40
              }
            }
          }
        },
        "facebook": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "hook",
            "blocks",
            "cta"
          ],
          "properties": {
            "hook": {
              "type": "string",
              "minLength": 1,
              "maxLength": 180,
              "description": "Abertura clara e convidativa para Facebook."
            },
            "blocks": {
              "type": "array",
              "minItems": 2,
              "maxItems": 4,
              "description": "Blocos curtos, explicativos e comerciais da legenda de Facebook. Cada bloco deve ter de 1 a 3 frases.",
              "items": {
                "type": "string",
