={{ (() => {
  const upload = ($json && typeof $json === "object") ? $json : {};
  const media = (() => {
    try {
      return $("Prepare Media Upload Batch").item.json || {};
    } catch {
      return {};
    }
  })();

  function str(value, fallback = "") {
    return value === undefined || value === null ? fallback : String(value);
  }

  function asObj(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : {};
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function num(value, fallback = 0) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? parsed : fallback;
  }

  function uniq(arr) {
    return [...new Set(asArray(arr).filter(Boolean).map((value) => str(value, "").trim()).filter(Boolean))];
  }

  function ensureHttps(url) {
    return str(url, "").replace(/^http:\/\//i, "https://");
  }

  function normalizeMimeFromUpload(resourceType, format) {
    const type = str(resourceType, "").toLowerCase();
    const fmt = str(format, "").toLowerCase();
    if (type === "video") {
      if (fmt === "mov") return "video/quicktime";
      if (fmt) return "video/" + fmt;
      return "video/mp4";
    }
    if (type === "image") {
      if (fmt === "jpg") return "image/jpeg";
      if (fmt) return "image/" + fmt;
      return "image/jpeg";
    }
    return "";
  }

  function ensureBestFrame(rawBestFrame, isVideo, technicalFrameCandidates) {
    const raw = asObj(rawBestFrame);
    if (!isVideo) {
      return {
        applicable: false,
        bestTimestamp: "",
        bestTimestampSeconds: 0,
        bestFrameSeconds: 0,
        reason: "",
        confidence: 0,
        candidates: [],
        thumbPath: "",
        selectedFrameUrl: "",
        selectedFrameRank: 0,
        selectedFrameSource: "none",
      };
    }

    return {
      applicable: raw.applicable === true || technicalFrameCandidates.length > 0 || Boolean(str(raw.selectedFrameUrl || raw.thumbPath || "", "")),
      bestTimestamp: str(raw.bestTimestamp || "", ""),
      bestTimestampSeconds: num(raw.bestTimestampSeconds ?? raw.timestampSeconds ?? raw.bestFrameSeconds ?? 0, 0),
      bestFrameSeconds: num(raw.bestFrameSeconds ?? raw.bestTimestampSeconds ?? raw.timestampSeconds ?? 0, 0),
      reason: str(raw.reason || "", ""),
      confidence: num(raw.confidence ?? 0, 0),
      candidates: technicalFrameCandidates,
      thumbPath: str(raw.thumbPath || media.thumbPath || "", ""),
      selectedFrameUrl: str(raw.selectedFrameUrl || "", ""),
      selectedFrameRank: num(raw.selectedFrameRank ?? 0, 0),
      selectedFrameSource: str(raw.selectedFrameSource || (technicalFrameCandidates.length ? "process_media_asset" : "none"), technicalFrameCandidates.length ? "process_media_asset" : "none"),
    };
  }

  const resourceType = str(upload.resource_type || media.resource_type || "", "").toLowerCase();
  const uploadMimeType = normalizeMimeFromUpload(resourceType, upload.format);
  const mediaMimeType = str(media.mimeType || "", "").toLowerCase();
  const isVideo =
    resourceType === "video" ||
    mediaMimeType.startsWith("video/") ||
    Boolean(media.groupIsVideo) ||
    str(media.mediaKind || "", "").toLowerCase() === "video";
  const resolvedMimeType = isVideo
    ? (uploadMimeType || (mediaMimeType.startsWith("video/") ? mediaMimeType : "video/mp4"))
    : (uploadMimeType || mediaMimeType || "image/jpeg");
  const finalUrl = ensureHttps(upload.secure_url || upload.url || media.finalUrl || "");
  const technicalFrameCandidates = asArray(media.technicalFrameCandidates);
  const frameCandidates = asArray(media.frameCandidates).length
    ? asArray(media.frameCandidates)
    : technicalFrameCandidates;
  const frameCandidateCount = num(
    media.frameCandidateCount ||
      technicalFrameCandidates.length ||
      frameCandidates.length,
    technicalFrameCandidates.length || frameCandidates.length,
  );
  const warnings = uniq([
    ...asArray(media.warnings),
    ...asArray(upload.warnings),
    resourceType === "video" && !mediaMimeType.startsWith("video/")
      ? "attach_main_media_metadata_reconciled_mimetype_to_video"
      : "",
  ]);
  const bestFrame = ensureBestFrame(media.bestFrame, isVideo, technicalFrameCandidates);

  return {
    targetDate: str(media.targetDate || "", ""),
    postPrefix: str(media.postPrefix || "", ""),
    groupKey: str(media.groupKey || "", ""),
    groupOrder: num(media.groupOrder || 0, 0),
