    media_type: str(media.media_type || (isVideo ? "VIDEO" : "IMAGE"), ""),
    media_type_1st_requisition: str(media.media_type_1st_requisition || (isVideo ? "VIDEO" : "IMAGE"), ""),
    media_type_2nd_requisition: str(media.media_type_2nd_requisition || "", ""),
    media_type_instagram: str(media.media_type_instagram || (isVideo ? "REELS" : ""), ""),
