parameters.fileName:
={{ (() => {
  const defaultTmpDir = "/tmp";
  function resolveRuntimeTmpDir(value) {
    const normalized = String(value || "").trim().replace(/\\/g, "/").replace(/\/+$/g, "");
    if (normalized === defaultTmpDir || normalized.startsWith(`${defaultTmpDir}/`)) return normalized;
    return defaultTmpDir;
  }
  const tmpDir = resolveRuntimeTmpDir($vars.LIVIA_TMP_DIR);
  const rawName = String($("Download File").item.json.name || "");
  const rawMime = String($("Download File").item.json.mimeType || "").toLowerCase();
  const rawId = String($("Download File").item.json.id || $("Prepare Media Items").item.json.id || "");

  function safeBase(value) {
    const raw = String(value || "").replace(/^dt:/, "").split("/").pop().replace(/\.[^.]+$/, "");
    const cleaned = raw.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^A-Za-z0-9_-]+/g, "_").replace(/^_+|_+$/g, "");
    return cleaned || "media";
  }

  function safeExt(name, mime) {
    const fromName = String(name || "").split(".").pop().toLowerCase().replace(/[^a-z0-9]/g, "");
    const allowed = new Set(["mp4", "mov", "m4v", "webm", "mkv", "jpg", "jpeg", "png", "webp", "heic"]);
    if (allowed.has(fromName)) return "." + fromName;
    if (mime.startsWith("video/")) return ".mp4";
    if (mime.includes("jpeg") || mime.includes("jpg")) return ".jpg";
    if (mime.includes("png")) return ".png";
    if (mime.includes("webp")) return ".webp";
    return ".bin";
  }

  const nameBase = safeBase(rawName);
  const idSuffix = safeBase(rawId).slice(-8);
  const base = idSuffix ? `${nameBase}_${idSuffix}` : nameBase;
  const ext = safeExt(rawName, rawMime);
  return `${tmpDir}/${base}_temp${ext}`;
})() }}

parameters.jsonOutput:
={{ (() => {
  const current = ($json && typeof $json === "object") ? $json : {};
  const attachItems = (() => {
    try {
      return $("Attach Uploaded Main Media Metadata").all().map((item) => item.json || {});
    } catch {
      return [];
    }
  })();
  const tokenRoot = (() => {
    try {
      return $("Get Credential Tokens").first().json || {};
    } catch {
      return {};
    }
  })();
  const coverResults = asArray(current.liviaCoverResults);

  function coverForMedia(media) {
    const id = str(media.id || media.asset_id || media.public_id, "");
    const groupKey = str(media.groupKey, "");
    const groupOrder = Number(media.groupOrder || 0);
    return coverResults.find((entry) => {
      const row = asObj(entry);
      return (id && str(row.mediaId, "") === id) ||
        (groupKey && str(row.groupKey, "") === groupKey && Number(row.groupOrder || 0) === groupOrder);
    }) || null;
  }

  function str(value, fallback = "") {
    return value === undefined || value === null ? fallback : String(value);
  }

  function asObj(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : {};
  }

  function asArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function normalizeUnit(raw) {
    const compact = str(raw, "")
      .trim()
      .toUpperCase()
      .replace(/\s+/g, "")
      .replace(/[_-]/g, "");
    if (compact.includes("BARRA") && compact.includes("SUL")) return "bss";
    if (compact === "BARRASHOPPINGSUL" || compact === "BSS") return "bss";
    if (compact.includes("NOVO") && compact.includes("HAMBURGO")) return "nh";
    if (compact === "NOVOHAMBURGO" || compact === "NH") return "nh";
    return "";
  }

  function buildTokenVaultContext(root) {
    const tokens = asArray(asObj(root).items);
    const byUnit = {
      bss: { Unit: "BSS" },
      nh: { Unit: "NH" },
    };

    for (const token of tokens) {
      if (!token || token.active === false) continue;
      const unitKey = normalizeUnit(token.unit || asObj(token.metadata).legacy_columns?.Unit || "");
      if (!unitKey || !byUnit[unitKey]) continue;

      if (token.provider === "facebook") {
        const metadata = asObj(token.metadata);
        const metaAdsPublish = asObj(metadata.meta_ads_publish);
        const isMetaAdsPublish =
          str(token.id, "").includes("meta_ads_publish") ||
          str(metadata.purpose, "") === "meta_ads_publish" ||
          Object.keys(metaAdsPublish).length > 0;
        if (isMetaAdsPublish && byUnit[unitKey].fbId) continue;

        byUnit[unitKey].fbId = str((isMetaAdsPublish && metaAdsPublish.page_id) || token.fbId || token.external_account_id, "");
        byUnit[unitKey].fbToken = "__TOKEN_GATEWAY__";
        byUnit[unitKey].fbCredentialPurpose = isMetaAdsPublish ? "meta_ads_publish_fallback" : "organic_publish";
      } else if (token.provider === "instagram") {
        byUnit[unitKey].igId = str(token.igId || token.external_account_id, "");
        byUnit[unitKey].igToken = "__TOKEN_GATEWAY__";
      } else if (token.provider === "threads") {
        byUnit[unitKey].thId = str(token.thId || token.external_account_id, "");
        byUnit[unitKey].thToken = "__TOKEN_GATEWAY__";
      }
    }

    return {
      raw: asObj(root),
      facebook: {
        network: "facebook.com",
        version: "v25.0",
        id_bss: str(byUnit.bss.fbId, ""),
        id_nh: str(byUnit.nh.fbId, ""),
        token_bss: str(byUnit.bss.fbToken, ""),
        token_nh: str(byUnit.nh.fbToken, ""),
        endpoint_1st: "",
        endpoint_2nd: "feed",
      },
