      return videoStatus === "UPLOAD_COMPLETE" && uploadingStatus === "COMPLETE";
    }

    if (kind === "fb_reels_published") {
      const videoStatus = normalizeStatusValue(statusObj.video_status);
      const processingStatus = normalizeStatusValue(statusObj?.processing_phase?.status);
      const publishingStatus = normalizeStatusValue(statusObj?.publishing_phase?.publish_status);
      const publishingPhaseStatus = normalizeStatusValue(statusObj?.publishing_phase?.status);
      return videoStatus !== "ERROR" && processingStatus === "COMPLETE" &&
        publishingPhaseStatus === "COMPLETE" && publishingStatus === "PUBLISHED";
    }

    if (kind === "fb_feed_media") return hasId;

    const status = normalizeStatusValue(extractStatusAny(source));
    if (["FINISHED", "READY", "PUBLISHED", "SUCCESS", "COMPLETED", "DONE"].includes(status)) return true;

    const publishingStatus = normalizeStatusValue(statusObj?.publishing_phase?.publish_status);
    if (publishingStatus.includes("PUBLISH")) return true;

    return false;
  }

  const fallbackStatus = normalizeStatusValue(extractStatusAny(source));
  return ["FINISHED", "READY", "PUBLISHED", "SUCCESS", "COMPLETED", "DONE"].includes(fallbackStatus);
}

function getFatalStatus(job, body) {
  const platform = str(job.platform, "").trim().toLowerCase();
  const kind = str(job.checkKind, "").trim().toLowerCase();
  const fatalWords = ["ERROR", "FAILED", "FAIL", "EXPIRED", "REJECTED", "INVALID"];
  const isFatal = (value) => {
    const normalized = normalizeStatusValue(value);
    if (!normalized) return "";
    return fatalWords.find((word) => normalized === word || normalized.includes(word)) || "";
  };

  const source = asObject(body);

  if (platform === "instagram" || kind === "ig_creation") {
    const hit = isFatal(source.status_code) || isFatal(source.status);
    if (hit) return hit;
  }

  if (platform === "threads" || kind === "th_creation") {
    const hit = isFatal(source.status);
    if (hit) return hit;
  }

  if (platform === "facebook" || kind.startsWith("fb_")) {
    const statusObj = asObject(source.status);
    const candidates = [
      statusObj.video_status,
      statusObj?.uploading_phase?.status,
      statusObj?.processing_phase?.status,
      statusObj?.publishing_phase?.status,
      statusObj?.publishing_phase?.publish_status,
      extractStatusAny(source),
    ];
    for (const candidate of candidates) {
      const hit = isFatal(candidate);
      if (hit) return hit;
    }
  }

  return isFatal(extractStatusAny(source));
}

