    return id ? "file:" + id : "ungrouped";
  }

  function extractPublishTime(j) {
    return pickFirst(j.publishTime, j.media?.publishTime);
  }

  function normalizePlatform(value) {
    const s = str(value, "").trim().toLowerCase();
    if (s === "instagram") return "instagram";
    if (s === "facebook") return "facebook";
    if (s === "threads") return "threads";
    return "";
