}
const crmCatalogUnits = Object.entries(CRM_UNITS).map(([workflowUnit, crmUnit]) => ({ workflowUnit, crmUnit }));
return $input.all().map((item) => ({
  json: { ...(item.json || {}), crmCatalogUnits },
  binary: item.binary,
  pairedItem: item.pairedItem,
}));
